            except Exception:
                print("Error in Light Pass:")
                traceback.print_exc()
                self.window.use() # Ensure we switch back to window context

            # 2. Main Pass: Render Game World
            self.window.use()
            self.clear()
            if self.show_map: self.gui_camera.use(); self.draw_map_overlay(); return
            self.maze_camera.use()

            if self.generating:
                self.grid_shapes.draw()
                for cell in self.grid.each_cell():
                    cx, cy = self.renderer.get_pixel(cell.row, cell.column)
