    def _add_to_list(self, shapes, p1, p2, processed, thickness):
        wid = tuple(sorted([(round(p1[0],2), round(p1[1],2)), (round(p2[0],2), round(p2[1],2))]))
        if wid in processed: return
        processed.add(wid)
